import{_ as a,o as t,c as s,ai as i}from"./chunks/framework.DQi1ytmF.js";const g=JSON.parse('{"title":"Live page MCP","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai/dev-page.md","filePath":"guide/ai/dev-page.md"}'),o={name:"guide/ai/dev-page.md"};function n(d,e,r,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/ai/dev-page.md for this page in Markdown format</div><h1 id="live-page-mcp" tabindex="-1">Live page MCP <a class="header-anchor" href="#live-page-mcp" aria-label="Permalink to &quot;Live page MCP&quot;">​</a></h1><p>The running development tab publishes its named controls. A coding agent fills, clicks, and inspects <strong>that</strong> page — no second browser, no DOM reverse-engineering.</p><p><strong>Use it when</strong> a Cursor agent must drive or inspect the <code>ng serve</code> tab you already have open. <strong>Not when</strong> you are writing Craft away from a running app — use <a href="/craft/resources/ai-agents.html"><code>@craft-ts/mcp</code></a> for docs and skills. <strong>Not when</strong> you want to mutate a primitive without the UI — use the <code>registry.*</code> tools on the same local MCP.</p><h2 id="connect-the-local-mcp" tabindex="-1">Connect the local MCP <a class="header-anchor" href="#connect-the-local-mcp" aria-label="Permalink to &quot;Connect the local MCP&quot;">​</a></h2><p>The tool lives on <code>@craft-ts/function-registry-mcp</code>, not on the published <code>@craft-ts/mcp</code> docs server. From the craft-ts repo:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry:mcp</span></span></code></pre></div><p>Point Cursor at that stdio server. It already listens on <code>ws://127.0.0.1:3333</code> for the demo tab. Each tab keeps a stable <code>clientId</code> in <code>sessionStorage</code>.</p><h2 id="one-ready-tab" tabindex="-1">One ready tab <a class="header-anchor" href="#one-ready-tab" aria-label="Permalink to &quot;One ready tab&quot;">​</a></h2><p>Each tab has a <code>clientId</code> in <code>sessionStorage</code>. Duplicating a tab copies it; the broker assigns a new id (<code>hello/ok</code>) so the two tabs do not fight.</p><p>Omit <code>clientId</code> when <strong>exactly one tab is <code>ready</code></strong>. A ghost <code>reloading</code> card (HMR, F5) does not count. Two <code>ready</code> tabs → pass <code>clientId</code> from <code>registry.clients</code> (id, status, url). Never pick “latest”. The error is <code>Multiple ready page clients; clientId is required. Available clients: &lt;id&gt; ready &lt;url&gt;, &lt;id&gt; ready &lt;url&gt;</code>. Zero ready with several ghosts is <code>No ready page client. Reloading: &lt;id&gt; (last url &lt;url&gt;), &lt;id&gt; (last url &lt;url&gt;)</code>. Zero cards is <code>page client is not connected</code>.</p><p>Closing the tab sends <code>page/goodbye</code>; the card is dropped. Opening a new tab is a new id. If <code>page client &quot;&lt;id&gt;&quot; is not connected</code>, call <code>registry.clients</code> and retry without id when a single ready remains.</p><p>Closing without goodbye (crash) looks like reload for up to 20s.</p><h2 id="one-tool-page" tabindex="-1">One tool: <code>page</code> <a class="header-anchor" href="#one-tool-page" aria-label="Permalink to &quot;One tool: \`page\`&quot;">​</a></h2><p>Omit <code>act</code> to read the current surface. The broker <strong>always asks the live tab</strong> — a Craft <code>value:</code> that changed without a DOM mutation is still current. Pass <code>act</code> to run a batch, then receive the <strong>new</strong> state in the same round-trip.</p><p>Default <code>detail</code> is <code>&quot;controls&quot;</code>: the named interactive surface (id, role, accessible name, value, enabled, index, and <code>track</code> when the node is inside <code>forNode</code>). Pass <code>detail: &quot;dom-styles&quot;</code> only to debug layout or CSS — it is large and opt-in.</p><p><code>id</code> is the literal local name from the helper:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { button, craftComponent } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@craft-ts/component&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> SaveToolbar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> craftComponent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;SaveToolbar&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({}),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;save&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;button&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Save&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>That name is unique in the app graph (<code>assertInteractiveElementNamed</code>). The renderer writes <code>data-craft-name=&quot;save&quot;</code>. Do not prefix it with the component name. When <code>forNode</code> repeats the same id, pass <code>match.index</code> or <code>match.track</code>.</p><h2 id="fill-click-goto-ready" tabindex="-1">Fill, click, goto, ready <a class="header-anchor" href="#fill-click-goto-ready" aria-label="Permalink to &quot;Fill, click, goto, ready&quot;">​</a></h2><p><code>act: [{ &quot;goto&quot;: &quot;/login-form&quot; }]</code> navigates in the tab (Craft router). The WebSocket stays up. Prefer <code>goto</code> over clicking <code>navLink</code> — every nav item shares that id. Paths like <code>/login-form</code> and full URLs both work.</p><p>A <code>fill</code> sets the control and dispatches one <code>input</code> or <code>change</code> (then blur), so <code>CraftFieldDirective</code> validation and touched state run. A click is <code>act</code> with only <code>id</code>. The batch runs in order and stops on the first error.</p><p>While <code>ng serve</code> rebuilds, the socket drops but the broker <strong>keeps</strong> the client card. <code>page</code> waits until the tab is <code>ready</code> again (up to <code>timeoutMs</code>, default 20s). You do not poll.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/craft/resources/ai-agents.html">Coding agents</a> — which MCP to use for docs vs the live tab</li><li><a href="/craft/guide/testing/architecture.html">Architecture rules</a> — unique interactive names</li><li><a href="/craft/guide/advanced/observability.html">Observability</a> — primitive traces, not DOM</li></ul>`,25)])])}const k=a(o,[["render",n]]);export{g as __pageData,k as default};
